import {icons} from './icons.js';
'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,d=0)=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const act=(label,action,id='',kind='',ico='')=>`<button type="button" class="btn ${kind}" data-action="${action}" data-id="${esc(id)}">${ico?icon(ico):''}${esc(label)}</button>`;
const link=(label,action,id='')=>act(label,action,id,'text');
const labels={DRAFT:'草稿',SUBMITTED:'待资质审核',APPROVED:'审核通过',RETURNED:'退回补充',TEACHER:'教师确认',DEPARTMENT:'教研室确认',COLLEGE:'学院确认',SCHOOL:'学校审核',READY:'待归档',ARCHIVED:'已归档',OPEN:'进行中',CLOSED:'已关闭',RESOLVED:'已解决',ACTIVE:'已启用',INACTIVE:'已停用',VALID:'有效记录',PENDING:'排队中',RUNNING:'处理中',RETRY:'等待重试',FAILED:'处理失败',BLOCKED:'未接通 / 已阻断',DONE:'已完成',PREVIEW:'待确认导入',COMMITTED:'已入库',NOT_CONNECTED:'未对接',VALIDATED:'仅本地校验',EXPIRING:'有效期核对',BASE:'初始积分',RECALC:'重算差额',MANUAL:'人工调整',SUCCESS:'成功',DENIED:'已拦截',ERROR:'异常'};
const badge=(s)=>`<span class="badge ${['APPROVED','ARCHIVED','DONE','COMMITTED','RESOLVED','ACTIVE','SUCCESS'].includes(s)?'green-b':['FAILED','BLOCKED','RETURNED','DENIED','ERROR'].includes(s)?'red-b':'blue-b'}">${esc(labels[s]||s)}</span>`;
const empty=(s='暂无记录',desc='当前授权范围内没有符合筛选条件的数据。')=>`<div class="empty">${icon('data')}<h3>${esc(s)}</h3><p>${esc(desc)}</p></div>`;
const note=(s,warn=false)=>`<div class="info-banner ${warn?'warn':''}">${icon(warn?'warning':'help')}<div>${esc(s)}</div></div>`;
const json=o=>`<pre class="data-json">${esc(JSON.stringify(o,null,2))}</pre>`;
const ts=v=>v?new Date(v.endsWith('Z')?v:v+'Z').toLocaleString('zh-CN',{hour12:false}):'—';
const titles={home:'工作总览',todos:'统一待办',cockpit:'学校管理驾驶舱',records:'培训数据台账',qualifications:'教师资质管理',points:'教师积分激励',assessment:'三级考核管理',disputes:'数据核对与复核',organization:'教研室与二级学院管理',rules:'规则与周期',imports:'Excel 导入中心',exports:'导出与任务中心',permissions:'组织、账号与权限',settings:'基础配置与字典',audit:'操作日志与安全审计',sync:'数据接入与同步',operations:'运维与交付',notices:'政策通知',help:'操作指引'};
let me=null,csrf='',page='home',filter={},tablePage=1,periodId='',periods=[],teachers=[],orgs=[],view={},modalContext=null,renderSequence=0;
const can=p=>!!me?.permissions?.includes(p);
const teacherName=id=>teachers.find(t=>t.id===id)?.name|| (id===me?.user.id?me.user.name:'教师 '+String(id).slice(0,8));
const periodName=id=>periods.find(p=>p.id===id)?.name||'未选择周期';
const orgName=id=>orgs.find(o=>o.id===id)?.name||'—';
const query=o=>{const q=new URLSearchParams;for(const[k,v]of Object.entries(o))if(v!==''&&v!==null&&v!==undefined)q.set(k,String(v));return q.toString()};
const requestKey=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24)),x=>x.toString(16).padStart(2,'0')).join('');
const reasonFields=()=>field('reason','办理意见 / 调整原因','textarea','',{required:true,full:true,hint:'所有关键操作保存原值、新值、经办人、时间与原因。'})+field('basis','依据说明或材料编号','text','',{full:true,required:false});
async function api(path,{method='GET',body,raw=false,key}={}){
 const headers={};if(method!=='GET'){headers['X-CSRF-Token']=csrf;if(method!=='DELETE')headers['Idempotency-Key']=key||requestKey()}
 if(body!==undefined&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}
 let response;try{response=await fetch('/api'+path,{method,body,headers,credentials:'same-origin',cache:'no-store'})}catch{throw Error('网络连接中断。请检查学校网络后刷新；不要重复确认未知结果。')}
 if(!response.ok){let data;try{data=await response.json()}catch{data={detail:'服务暂不可用'}}
  if(response.status===401&&path!=='/auth/login'){me=null;loginView('登录已失效，请重新登录');closeModal()}
  const message=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail);
  throw Error(message+(data.errors?'\n'+data.errors.map(e=>e.field+'：'+e.message).join('\n'):'')+(data.request_id?'\n请求编号：'+data.request_id:''));}
 return raw?response:response.json();
}
function toast(message,error=false){let el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6000)}
function field(name,label,type='text',value='',opts={}){
 const attrs=`id="f-${name}" name="${name}" ${opts.required===false?'':'required'} ${opts.readonly?'readonly':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step?`step="${opts.step}"`:''}`;
 let input;if(type==='select')input=`<select ${attrs}>${(opts.options||[]).map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;
 else if(type==='textarea')input=`<textarea ${attrs} rows="${opts.rows||3}">${esc(value)}</textarea>`;
 else if(type==='checkbox')input=`<label class="flex"><input name="${name}" type="checkbox" ${value?'checked':''}>${esc(opts.checkLabel||'启用')}</label>`;
 else input=`<input type="${type}" ${attrs} value="${esc(value)}" ${opts.accept?`accept="${opts.accept}"`:''} ${type==='password'?'autocomplete="new-password"':''}>`;
 return `<div class="form-field ${opts.full?'full':''}"><label for="f-${name}">${esc(label)}${opts.required===false?'':' <b>*</b>'}</label>${input}${opts.hint?`<p class="hint">${esc(opts.hint)}</p>`:''}</div>`;
}
function teacherField(value=me?.user.id,name='teacher_id'){
 return `<div class="form-field"><label>教师（输入工号或姓名检索） <b>*</b></label><input name="${name}_search" class="teacher-lookup" list="teacher-options" value="${esc(teachers.find(t=>t.id===value)?.staff_no||'')}" placeholder="输入教师姓名或工号" autocomplete="off" required><input type="hidden" name="${name}" value="${esc(value||'')}"><datalist id="teacher-options">${teachers.map(t=>`<option value="${esc(t.staff_no)}">${esc(t.name)}</option>`).join('')}</datalist><p class="hint">仅可选择当前账号授权范围内的教师。</p></div>`;
}
function formValues(form){const values=Object.fromEntries(new FormData(form));$$('input[type=checkbox][name]',form).forEach(i=>values[i.name]=i.checked);$$('input[type=number][name]',form).forEach(i=>values[i.name]=i.value===''?null:Number(i.value));return values}
function modal(title,body,foot='',wide=false){$('#modal-root').innerHTML=`<section role="dialog" aria-modal="true" aria-label="${esc(title)}" class="modal ${wide?'wide':''}"><header class="modal-head"><div><h2>${esc(title)}</h2><p>以服务端保存结果为准 · 操作留痕</p></div>${act('','close','','icon-btn','close')}</header><div class="modal-body">${body}</div><footer class="modal-foot">${foot||act('关闭','close')}</footer></section>`;$('#modal-root').classList.remove('hidden');setTimeout(()=>$('input:not([type=hidden]),textarea,select,button',$('#modal-root'))?.focus(),30)}
function formModal(title,body,callback,{wide=false,submit='保存',hint=''}={}){
 modal(title,`${hint?note(hint):''}<form id="edit-form"><div id="form-error"></div><div class="form-grid mt16">${body}</div></form>`,act('取消','close')+`<button type="submit" form="edit-form" class="btn primary">${esc(submit)}</button>`,wide);
 const form=$('#edit-form');form.addEventListener('submit',async e=>{e.preventDefault();const button=$('button[form=edit-form]');button.disabled=true;$('#form-error').innerHTML='';try{await callback(formValues(form),form)}catch(err){if($('#form-error'))$('#form-error').innerHTML=`<div class="error-text">${esc(err.message)}</div>`;else toast(err.message,true)}finally{if(button.isConnected)button.disabled=false}});
}
function closeModal(){$('#modal-root').classList.add('hidden');$('#modal-root').innerHTML='';modalContext=null}
const detailSections=(obj)=>`<details class="mt16"><summary class="blue small">查看完整字段与追溯依据</summary>${json(obj)}</details>`;
const eventsHtml=events=>events?.length?`<div class="timeline event-list mt16">${events.map(e=>`<div class="timeline-item"><strong>${esc(e.action)}</strong><small>${esc(e.actor_name)} · ${ts(e.created_at)}</small><p>${esc(e.reason)}${e.basis?' · '+esc(e.basis):''}</p></div>`).join('')}</div>`:empty('尚无流转记录');
const downloads=items=>items?.length?items.map(a=>`<div class="upload-meta mt8">${icon('file')}<div class="grow"><strong>${esc(a.name)}</strong><p class="muted small">${number(a.size/1024,1)} KiB · SHA256 ${esc(a.sha256?.slice(0,14))}…</p></div>${act('查看 / 下载','attachment-download',a.id,'sm','download')}</div>`).join(''):note('尚未上传附件。资质提交审核前必须上传真实文件。',true);
function table(headers,rows){return rows.length?`<div class="table-scroll"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty()}
function pager(data){return `<div class="pagination"><span>共 ${number(data.total)} 条 · 第 ${data.page} 页</span><div class="pages"><button data-action="prev" ${data.page<=1?'disabled':''}>上一页</button><button class="active">${data.page}</button><button data-action="next" ${data.page*data.size>=data.total?'disabled':''}>下一页</button></div></div>`}
const periodSelect=()=>`<select id="period-filter" class="period-name"><option value="">全部周期</option>${periods.map(p=>`<option value="${p.id}" ${p.id===periodId?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`;
function pageHead(desc='',actions=''){return `<div class="pagehead"><div><div class="eyebrow">NON-DEGREE EDUCATION</div><h1>${titles[page]}</h1><p>${esc(desc)}</p></div><div class="page-actions">${actions}</div></div>`}
function filtersBar({search=true,states=[],period=false,dates=false,teacher=false,organization=false,project=false,exportKind=''}={}){
 return `<form id="filters" class="filterbar">${search?`<div class="field-search">${icon('search')}<input name="q" placeholder="搜索名称或编号" value="${esc(filter.q||'')}"></div>`:''}${period?periodSelect():''}${states.length?`<select name="state"><option value="">全部状态</option>${states.map(s=>`<option value="${s}" ${filter.state===s?'selected':''}>${labels[s]||s}</option>`).join('')}</select>`:''}${dates?`<input name="start" type="date" aria-label="开始日期" value="${esc(filter.start||'')}"><span class="muted small">至</span><input name="end" type="date" aria-label="结束日期" value="${esc(filter.end||'')}">`:''}${organization?`<select name="org_id"><option value="">全部授权组织</option>${orgs.filter(o=>o.kind!=='school').map(o=>`<option value="${o.id}" ${filter.org_id===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`:''}${teacher?`<input class="filter-teacher" name="teacher_search" list="filter-teacher-list" placeholder="教师工号检索" value="${esc(teachers.find(t=>t.id===filter.teacher_id)?.staff_no||'')}"><datalist id="filter-teacher-list">${teachers.map(t=>`<option value="${esc(t.staff_no)}">${esc(t.name)}</option>`).join('')}</datalist>`:''}${project?`<input name="project_code" placeholder="项目编码" value="${esc(filter.project_code||'')}"><input name="course_code" placeholder="课程编码" value="${esc(filter.course_code||'')}">`:''}<button class="btn primary" type="submit">查询</button>${act('重置','reset-filters','','')}${exportKind&&can('export')?act('导出 Excel','export',exportKind,'','export'):''}</form>`;
}
function loginView(message=''){
 $('#app').innerHTML=`<div class="login-shell"><section class="login-story"><div class="flex">${icon('school')}<strong>跃科 · 智慧教育</strong></div><h1>数据有依据<br>办事有闭环</h1><p>一站式非学历教育智慧前台<br>把资质、积分、考核与分级管理，汇聚到一个工作入口。</p><div class="login-features"><span>教师本人办理</span><span>四级组织权限</span><span>学校本地部署</span></div></section><section class="login-form-shell"><form id="login-form" class="login-form"><h2>欢迎登录</h2><p>使用学校管理员为你开通的账号。</p><div id="login-error">${message?`<div class="error-text">${esc(message)}</div>`:''}</div><div class="form-field"><label for="username">账号</label><input id="username" name="username" autocomplete="username" required placeholder="输入账号"></div><div class="form-field"><label for="password">密码</label><input id="password" name="password" autocomplete="current-password" type="password" required placeholder="输入密码"></div><button class="btn primary" type="submit">登录工作台 ${icon('arrow')}</button><div class="login-foot">忘记密码请联系学校管理员。<br>统一认证对接完成前，使用本地账号认证。<br>湖南跃科信息工程有限公司</div></form></section></div>`;
 $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{const v=formValues(e.target);await api('/auth/login',{method:'POST',body:v});await boot()}catch(err){$('#login-error').innerHTML=`<div class="error-text">${esc(err.message)}</div>`}finally{if(b.isConnected)b.disabled=false}});
}
function navItems(){return [
 ['工作空间',[['home','home','portal.read'],['todos','tasks','portal.read'],...(me.role.kind==='school'?[['cockpit','chart','portal.read']]:[])]],
 ['业务办理',[['records','data','records.read'],['qualifications','cert','qualification.read'],['points','award','points.read'],['assessment','assess','assessment.read'],['disputes','help','dispute.write'],['organization','org','organization.read']]],
 ['数据与支撑',[['rules','settings','rules.manage'],['imports','download','import'],['exports','export','export'],['permissions','shield','users.manage'],['settings','settings','settings.manage'],['sync','sync','sync.manage'],['audit','logs','audit.read'],['operations','server','operations.read'],['notices','notice','notice.read']]]
 ].map(([group,items])=>[group,items.filter(x=>can(x[2]))]);}
function shell(){
 $('#app').innerHTML=`<aside id="sidebar" class="sidebar"><div class="brand"><div class="brand-logo">${icon('school')}</div><div><div class="brand-title">跃科 · 智慧教育</div><div class="brand-sub">NON-DEGREE EDUCATION</div></div></div><div class="school-switch"><div class="school-icon">${icon('school')}</div><div><strong>${esc(me.school_name||'学校业务空间')}</strong><small>学校独立业务空间</small></div></div><nav class="nav-scroll">${navItems().map(([g,items])=>`<div class="nav-group">${g}</div>${items.map(([p,i])=>`<button type="button" data-action="nav" data-id="${p}" class="nav-item ${p===page?'active':''}">${icon(i)}${titles[p]}</button>`).join('')}`).join('')}</nav><div class="sidebar-foot">${act('操作指引','nav','help','','help')}<div class="powered">湖南跃科信息工程有限公司</div></div></aside><div class="main-shell"><header class="topbar">${act('','toggle-menu','','icon-btn mobile-nav','menu')}<div class="breadcrumb"><span class="hide-phone">非学历教育</span>${icon('chevron')}<strong id="breadcrumb">${titles[page]}</strong></div><div class="header-actions"><button class="search-trigger" data-action="search">${icon('search')}<span>搜索菜单与业务</span><kbd>/</kbd></button><span class="app-flag">${me.environment==='test'?'隔离验收演练环境':'学校本地部署'}</span>${act('','nav','todos','icon-btn','bell')}<div class="identity"><span class="avatar">${esc(me.user.name.slice(0,1))}</span><div class="current-identity"><strong>${esc(me.user.name)}</strong><small>${esc(me.role.name)}</small></div>${act('','profile','','icon-btn','settings')}${act('','logout','','icon-btn','logout')}</div></div></header><main id="content" class="content"></main></div>`;
}
async function boot(){
 const data=await api('/auth/me');me=data;csrf=data.csrf;
 if(me.user.must_change_password){shell();$('#content').innerHTML=pageHead('首次使用前，请修改管理员分配的临时密码。');changePassword(true);return}
 [periods,teachers,orgs]=await Promise.all([api('/periods'),api('/teachers?size=200'),api('/organizations')]).then(r=>r.map(x=>x.items));
 const dest=location.hash.replace('#','').split('?')[0];if(dest&&titles[dest])page=dest;
 shell();await render();
}
function nav(dest,extra={}){if(!titles[dest])return;page=dest;filter=extra;tablePage=1;location.hash=dest;$('#sidebar')?.classList.remove('open');return render()}
async function render(){
 if(!me)return;const seq=++renderSequence;$('#breadcrumb').textContent=titles[page];$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.id===page));
 $('#content').innerHTML='<div class="busy-panel">正在读取授权业务数据…</div>';
 try{const html=await pages[page]();if(seq!==renderSequence)return;$('#content').innerHTML=html+`<footer class="footer"><span>跃科 · 一站式非学历教育智慧前台</span><span>权限范围：${esc(me.role.kind==='teacher'?'仅本人':orgName(me.user.org_id))} · 服务端统一统计口径</span></footer>`;bindFilters()}
 catch(err){if(seq===renderSequence&&$('#content'))$('#content').innerHTML=pageHead()+note(err.message,true)+`<div class="mt16">${act('重新读取','refresh')}</div>`;}
}
function bindFilters(){const form=$('#filters');if(!form)return;form.addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));if(v.teacher_search){const t=teachers.find(t=>t.staff_no===v.teacher_search);if(!t){toast('请检索并选择一个授权教师工号',true);return}v.teacher_id=t.id}delete v.teacher_search;periodId=$('#period-filter')?.value||periodId;filter=v;tablePage=1;render()});}
const listQuery=(usePeriod=false)=>query({...filter,page:tablePage,size:20,...(usePeriod&&periodId?{period_id:periodId}:{})});
const metricsHTML=s=>`<div class="kpis">${[['归属培训收入',number(s.income,2),'元','wallet','records'],['课程人次',number(s.participants),'人次','users','records'],['参与教师',number(s.teachers),'人','users','organization'],['培训项目',number(s.projects),'个','book','records']].map(([l,v,u,i,p])=>`<button class="kpi" data-action="nav" data-id="${p}"><span class="kpi-label">${l}</span><span class="kpi-icon">${icon(i)}</span><div class="kpi-value">${v}<small>${u}</small></div><div class="kpi-foot">当前筛选范围 · 点击查看业务明细</div></button>`).join('')}</div>`;
function trendHTML(s){const max=Math.max(1,...s.trend.map(x=>Number(x.income)));return `<div class="card"><div class="card-head"><div><h2>培训收入趋势</h2><p>按业务日期月份汇总 · 与台账同源</p></div>${act('业务明细','nav','records','text','arrow')}</div><div class="card-pad">${s.trend.length?`<div class="line-chart">${s.trend.map(x=>`<div class="chart-bar" style="height:${Math.max(2,Number(x.income)/max*125)}px" title="${esc(x.month)}：${esc(x.income)} 元"><span>${number(x.income/10000,1)}万</span></div>`).join('')}</div><div class="chart-months">${s.trend.map(x=>`<span>${x.month}</span>`).join('')}</div>`:empty('暂无收入趋势')}</div><div class="card-foot">负向更正可能导致月份净收入为负；准确金额见台账。</div></div>`}
function rankHTML(s){const a=s.colleges,max=Math.max(1,...a.map(x=>Number(x.income)));return `<div class="card"><div class="card-head"><h2>学院培训收入</h2><span class="small muted">元</span></div><div class="ranking">${a.length?a.map((x,i)=>`<div class="rank-row"><span class="rank-no">${String(i+1).padStart(2,'0')}</span><div class="grow"><div class="rank-title"><span>${esc(x.name)}</span><strong>${number(x.income,2)}</strong></div><div class="track"><div class="fill" style="width:${Math.max(0,Number(x.income)/max*100)}%"></div></div></div>${act('','drill-org',x.id,'text','chevron')}</div>`).join(''):empty()}</div></div>`}
function todosHTML(items){return items.length?`<div class="task-list">${items.slice(0,6).map(x=>`<div class="task-row"><span class="task-icon">${icon(x.type==='qualification'?'cert':x.type==='assessment'?'assess':'help')}</span><div class="grow"><div class="task-title">${esc(x.title)}</div><div class="task-sub">${x.teacher_id?esc(teacherName(x.teacher_id))+' · ':''}${esc(labels[x.state]||x.state)}</div></div>${act('去办理','todo',`${x.type}|${x.id}`,'sm')}</div>`).join('')}</div>`:empty('当前没有待办','新资质、核对申请和考核确认会在这里自动汇集。')}
const pages={
 async home(){const[s,t,n]=await Promise.all([api('/statistics'),api('/todos'),api('/notices?size=4')]);let personal='';if(me.role.kind==='teacher'){const[q,p,a]=await Promise.all([api('/qualifications?size=1&state=APPROVED'),api('/points?'+query({size:1,period_id:periodId})),api('/assessments?'+query({size:1,period_id:periodId}))]);const latest=a.items[0];personal=`<div class="summary-row"><div class="summary-item"><label>审核通过的本人资质</label><strong>${q.total}<small>份</small></strong></div><div class="summary-item"><label>当前周期积分</label><strong>${number(p.sum,2)}<small>分</small></strong></div><div class="summary-item"><label>当前周期考核得分</label><strong>${latest?number(latest.score,2):'—'}</strong></div><div class="summary-item"><label>当前考核环节</label><div class="mt12">${latest?badge(latest.state):'尚未生成考核'}</div></div></div>`}view={s,t,n};return pageHead('从数据核对到考核归档，今天的工作从这里开始。',act('刷新数据','refresh','','','refresh'))+`<section class="banner"><div><div class="eyebrow">YOUR WORKSPACE</div><h2>${esc(me.user.name)}，欢迎回到工作台</h2><p>当前有 ${t.total} 项事项需要关注。资质、积分与考核依据均可追溯，请先核对，再确认。</p></div><div class="banner-next"><div class="pending"><b>${t.total}</b> 项待办</div>${act('查看我的待办','nav','todos','white','arrow')}</div></section>`+metricsHTML(s)+personal+`<div class="cols2">${trendHTML(s)}<div class="card"><div class="card-head"><h2>待办事项</h2>${link('全部待办','nav','todos')}</div>${todosHTML(t.items)}</div></div><div class="equal2 mt20"><div class="card"><div class="card-head"><h2>高频业务</h2></div><div class="quick-grid">${[['qualifications','cert','维护教师资质'],['points','award','核对积分明细'],['assessment','assess','办理考核确认'],['records','data','查看培训台账']].map(([p,i,l])=>`<button class="quick" data-action="nav" data-id="${p}"><span class="qicon">${icon(i)}</span>${l}</button>`).join('')}</div><div class="card-foot">所有操作绑定真实登录账号，不能切换他人身份代确认。</div></div><div class="card"><div class="card-head"><h2>政策通知</h2>${link('查看全部','nav','notices')}</div><div class="card-pad">${n.items.map(x=>`<button class="notice-row" data-action="notice" data-id="${x.id}"><span>${esc(x.title)}</span><time>${x.created_at.slice(5,10)}</time></button>`).join('')||empty('暂无政策通知')}</div></div></div><div class="mt20">${note(s.metric_notes.income_note+' '+s.metric_notes.participants_note)}</div>`},
 async cockpit(){const q=query({...filter,...(periodId?{period_id:periodId}:{})}),s=await api('/statistics?'+q);view={s};return pageHead('全校运行态势 · 学院对比 · 同源统计',act('查看数据明细','nav','records','','data'))+`<div class="card mb16">${filtersBar({period:true,dates:true,organization:true,teacher:true,project:true})}</div>`+metricsHTML(s)+`<div class="cols2">${trendHTML(s)}${rankHTML(s)}</div><div class="equal2 mt20"><div class="card"><div class="card-head"><h2>考核处理进度</h2></div>${table(['环节','教师数量'],Object.entries(s.assessment_states).map(([k,v])=>[badge(k),link(String(v),'drill-state',k)]))}<div class="card-foot">考核统计按当前周期与组织 / 教师范围；时间与项目筛选仅作用于培训业务指标。</div></div><div class="card card-pad"><h2>运行规模与接口状态</h2><div class="two-numbers mt20"><div><strong class="inline-metric">${s.courses}</strong><p class="metric-label">课程</p></div><div><strong class="inline-metric">${s.classes}</strong><p class="metric-label">班级</p></div><div><strong class="inline-metric">${number(s.hours,2)}</strong><p class="metric-label">授课学时</p></div></div><div class="divider"></div>${badge('NOT_CONNECTED')}<p class="note-text mt12">学校数据中台与省级平台尚未真实接入；本地业务不冒充省级同步成功。</p><div class="mt16">${act('数据接入与同步','nav','sync','','sync')}</div></div></div>`},
 async todos(){const d=await api('/todos');view=d;return pageHead('审核、核对、资质有效期与考核确认集中办理。')+`<div class="card"><div class="card-head"><h2>全部待办</h2><span class="subtle">${d.total} 项</span></div>${table(['事项','所属教师','状态','办理'],d.items.map(x=>[esc(x.title),esc(teacherName(x.teacher_id)),badge(x.state),act('去办理','todo',`${x.type}|${x.id}`,'sm')]))}</div>`},
 async records(){const d=await api('/records?'+listQuery(true));view=d;return pageHead('收入与人次以业务台账为准；更正保留版本，已归档快照不受影响。',can('records.write')?act('新增业务记录','record-form','','primary','plus'):'')+`<div class="card">${filtersBar({period:true,dates:true,teacher:true,organization:me.role.kind!=='teacher',project:true,exportKind:'records'})}${table(['业务日期 / 来源编号','教师','项目 / 课程','班级','学时','人次','归属收入（元）','操作'],d.items.map(x=>[`<strong>${esc(x.event_date)}</strong><div class="cell-sub">${esc(x.external_key)}</div>`,esc(teacherName(x.teacher_id)),`<strong>${esc(x.project)}</strong><div class="cell-sub">${esc(x.course)}</div>`,esc(x.class_name),number(x.hours,2),number(x.participants),number(x.income,2),link('查看依据','record',x.id)+(can('records.write')?link('更正','record-form',x.id):'')]))}${pager(d)}</div>`},
 async qualifications(){const d=await api('/qualifications?'+listQuery());view=d;return pageHead('上传真实佐证 → 教师提交 → 授权审核 → 版本归档与到期提醒。',can('qualification.write')&&me.user.staff_no?act('新增我的资质','qualification-form','','primary','plus'):'')+`<div class="card">${filtersBar({states:['DRAFT','SUBMITTED','RETURNED','APPROVED'],teacher:me.role.kind!=='teacher',exportKind:'qualifications'})}${table(['证书名称 / 类别','教师','证书编号','有效期至','状态','版本','操作'],d.items.map(x=>[`<strong>${esc(x.name)}</strong><div class="cell-sub">${esc(x.category)}</div>`,esc(teacherName(x.teacher_id)),esc(x.certificate_no),esc(x.expires||'长期有效'),badge(x.state),'v'+x.version,link('查看 / 办理','qualification',x.id)]))}${pager(d)}</div>`},
 async points(){const[d,b]=await Promise.all([api('/points?'+listQuery(true)),api('/point-balances?'+query({period_id:periodId}))]);view={...d,balances:b.items};return pageHead('查看原始值、计算公式与规则版本；纠错只追加调整项。',(can('points.calculate')?act('计算 / 重算','calculate','points','primary','refresh'):'')+(can('points.adjust')?act('追加调整项','point-adjust','','','plus'):''))+`<div class="summary-row"><div class="summary-item"><label>当前范围积分合计</label><strong>${number(d.sum,2)}<small>分</small></strong></div><div class="summary-item"><label>积分流水</label><strong>${d.total}<small>笔</small></strong></div><div class="summary-item"><label>已确认台账</label><strong>${b.items.filter(x=>x.confirmed).length}<small>份</small></strong></div><div class="summary-item"><label>当前周期</label><p class="mt12 small">${esc(periodId?periodName(periodId):'全部周期')}</p></div></div><div class="card">${filtersBar({search:false,period:true,teacher:me.role.kind!=='teacher',exportKind:'points'})}${table(['教师','积分项','变动类型','分值','计算时间','操作'],d.items.map(x=>[esc(teacherName(x.teacher_id)),esc(x.item_key),badge(x.kind),`<strong>${Number(x.amount)>0?'+':''}${number(x.amount,2)}</strong>`,ts(x.created_at),link('计算依据','point',x.id)]))}${pager(d)}</div><div class="card mt20"><div class="card-head"><h2>教师积分确认</h2><span class="subtle">确认后冻结；授权解锁必须填写原因</span></div>${table(['教师','周期','确认状态','操作'],b.items.map(x=>[esc(teacherName(x.teacher_id)),esc(periodName(x.period_id)),badge(x.confirmed?'已确认':'待本人确认'),x.teacher_id===me.user.id&&!x.confirmed?act('本人确认','balance-action',x.id,'sm'):x.confirmed&&can('points.adjust')?act('留痕解锁','balance-action',x.id,'sm'):'—']))}</div>`},
 async assessment(){const d=await api('/assessments?'+listQuery(true));view=d;return pageHead('自动取数与评分 → 教师 → 教研室 → 学院 → 学校 → 归档。',can('assessment.calculate')?act('生成 / 重算考核','calculate','assessment','primary','refresh'):'')+`<div class="flow-strip">${['数据采集','自动计算','教师确认 / 核对','教研室确认','学院确认','学校审核','归档'].map((x,i)=>`<div class="flow-step"><i>${i+1}</i>${x}</div>`).join('')}</div><div class="card">${filtersBar({search:false,period:true,teacher:me.role.kind!=='teacher',states:['TEACHER','DEPARTMENT','COLLEGE','SCHOOL','READY','ARCHIVED'],exportKind:'assessments'})}${table(['范围序号','教师','考核周期','得分','当前环节','是否退回','操作'],d.items.map(x=>[x.scope_rank,esc(teacherName(x.teacher_id)),esc(periodName(x.period_id)),`<strong class="blue">${number(x.score,2)}</strong>`,badge(x.state),x.returned?badge('RETURNED'):'—',link('查看 / 办理','assessment',x.id)]))}${pager(d)}<div class="card-foot">${esc(d.rank_note)}</div></div>`},
 async disputes(){const d=await api('/disputes?'+listQuery(true));view=d;return pageHead('从业务明细发起核对，复核人与申请人分离；未解决前阻止考核确认。')+`<div class="card">${filtersBar({search:false,states:['OPEN','RESOLVED'],period:true})}${table(['提交时间','教师','业务对象','核对原因','状态','操作'],d.items.map(x=>[ts(x.created_at),esc(teacherName(x.teacher_id)),esc({record:'培训数据',points:'积分',assessment:'考核'}[x.object_type]),`<span title="${esc(x.reason)}">${esc(x.reason.slice(0,45))}</span>`,badge(x.state),link('查看 / 复核','dispute',x.id)]))}${pager(d)}</div>`},
 async organization(){const s=await api('/statistics?'+query({...filter,...(periodId?{period_id:periodId}:{})}));view={s};return pageHead('按组织自动限定业务范围，逐层查看教师与明细。')+`<div class="card mb16">${filtersBar({period:true,organization:true,teacher:true,dates:true,project:true,exportKind:'records'})}</div>`+metricsHTML(s)+`<div class="card"><div class="card-head"><h2>教研室运行概览</h2></div>${table(['教研室','归属培训收入（元）','课程人次','参与教师','查看'],s.ranking.map(x=>[esc(x.name),number(x.income,2),number(x.participants),x.teachers,link('穿透业务明细','drill-org',x.org_id)]))}</div>`},
 async rules(){const d=await api('/rules?'+query({period_id:periodId}));view=d;return pageHead('规则不可覆盖修改；先复制新版本，再试算启用。',(can('settings.manage')?act('新增周期','period-form','','','plus'):'')+act('新增规则','rule-form','','primary','plus'))+`<div class="card">${filtersBar({search:false,period:true})}${table(['规则名称','类型','周期','版本','状态','操作'],d.items.map(x=>[esc(x.name),x.kind==='points'?'积分激励':'三级考核',esc(periodName(x.period_id)),x.version_no,badge(x.state),link('详情 / 试算','rule',x.id)+link('复制新规则','rule-form',x.id)]))}</div><div class="card mt20"><div class="card-head"><h2>考核周期</h2><span class="subtle">关闭周期前，所有考核须归档且无未解决核对</span></div>${table(['周期','开始','结束','状态','操作'],periods.map(p=>[esc(p.name),p.start_date,p.end_date,badge(p.state),p.state==='OPEN'?link('关闭周期','close-period',p.id):'—']))}</div>`},
 async imports(){const d=await api('/imports?'+listQuery());view=d;return pageHead('下载标准模板 → 上传校验 → 查看错误行 → 明确确认 → 真实入库。',act('上传 Excel','import-form','','primary','plus'))+note('教师批量导入创建的是“停用待配置”账号。管理员重置临时密码并启用后才能登录；资质批量导入为草稿，仍需本人补充附件。')+`<div class="subnav-grid mt16">${[['records','培训数据'],['qualifications','教师资质'],['teachers','教师账号']].map(([k,v])=>`<button data-action="template" data-id="${k}">${icon('download')} <strong>${v}模板.xlsx</strong><p>固定表头 · 服务端校验 · 不含真实个人数据</p></button>`).join('')}</div><div class="card mt20">${table(['上传文件','类型','数据行','错误行','状态','操作'],d.items.map(x=>[esc(x.filename),esc({records:'培训数据',qualifications:'资质',teachers:'教师账号'}[x.kind]),x.total,x.errors,badge(x.state),link('查看 / 确认','import',x.id)]))}${pager(d)}</div>`},
 async exports(){const d=await api('/tasks?'+query({page:tablePage,size:20,kind:'export'}));view=d;return pageHead('后台生成 Excel 与开放格式移交包；下载时再次校验权限。',act('刷新任务','refresh','','','refresh')+(can('data.export')?act('生成结构化移交包','export','handover','','export'):''))+`<div class="card">${table(['创建时间','导出类型','状态','处理尝试','说明','操作'],d.items.map(x=>[ts(x.created_at),esc(x.payload.kind),badge(x.state),x.attempts,esc(x.error||x.result?.filename||'后台处理'),link('任务详情','task',x.id)+(x.state==='DONE'?link('下载文件','task-download',x.id):'')]))}${pager(d)}</div>`},
 async permissions(){const[u,r,o]=await Promise.all([api('/users?'+listQuery()),api('/roles'),api('/organizations')]);orgs=o.items;view={users:u.items,roles:r.items,...u};return pageHead('账号绑定组织和角色；组织或角色变更即时改变数据范围。',act('新增组织','org-form','','','plus')+act('新增账号','user-form','','primary','plus'))+`<div class="card">${filtersBar()}${table(['账号 / 工号','姓名','组织','角色','状态','操作'],u.items.map(x=>[`<strong>${esc(x.username)}</strong><div class="cell-sub">${esc(x.staff_no||'管理账号')}</div>`,esc(x.name),esc(orgName(x.org_id)),esc(r.items.find(y=>y.id===x.role_id)?.name),badge(x.active?'已启用':'INACTIVE'),link('编辑','user-form',x.id)+link('重置密码','reset-password',x.id)]))}${pager(u)}</div><div class="card mt20"><div class="card-head"><h2>角色与批量授权</h2><span class="subtle">菜单 / 操作 / 数据 / 导出权限</span></div>${table(['角色','层级','权限数','状态','操作'],r.items.map(x=>[esc(x.name),esc(x.kind),x.permissions.length,badge(x.active?'ACTIVE':'INACTIVE'),link('批量授权','role-permissions',x.id)+link('复制角色','role-copy',x.id)]))}</div><div class="card mt20"><div class="card-head"><h2>组织机构</h2></div>${table(['组织编码','名称','层级','上级','状态','操作'],orgs.map(x=>[esc(x.code),esc(x.name),esc({school:'学校',college:'二级学院',dept:'教研室'}[x.kind]),esc(orgName(x.parent_id)),badge(x.active?'ACTIVE':'INACTIVE'),link('编辑','org-form',x.id)+(x.kind!=='school'?link(x.active?'停用':'启用','org-state',x.id):'')]))}</div>`},
 async settings(){const d=await api('/settings');view=d;return pageHead('统一字典与展示口径；关键配置变更必须说明原因。')+`<div class="cols3">${d.items.map(x=>`<div class="card card-pad"><h2>${esc({branding:'学校品牌',qualification:'资质字典与到期提醒',metrics:'统计口径说明'}[x.key]||x.key)}</h2><div class="small muted mt8">配置版本 ${x.version}</div>${json(x.value)}<div class="mt16">${act('修改配置','setting',x.key,'primary','edit')}</div></div>`).join('')}</div>`},
 async audit(){const d=await api('/audit?'+listQuery());view=d;return pageHead('登录、查询、导出、审核、权限和配置调整均记录服务端审计。')+`<div class="card">${filtersBar({exportKind:'audit'})}${table(['操作时间','操作人','模块','操作','业务对象','结果','详情'],d.items.map(x=>[ts(x.created_at),esc(x.actor_name),esc(x.module),esc(x.action),`<span class="mono">${esc(x.object_id?.slice(0,25))}</span>`,badge(x.result),link('前后值','audit-detail',x.id)]))}${pager(d)}</div>`},
 async sync(){const[c,t]=await Promise.all([api('/connections'),api('/tasks?kind=sync&size=30')]);view={connections:c.items,tasks:t.items};return pageHead('维护接口登记与字段映射；真实外部对接暂不在本次范围内。')+note('配置参数或本地报文校验不等于联调成功。本版本不向外部系统发送数据，真实连接默认关闭。',true)+`<div class="cols3 mt16">${c.items.map(x=>`<div class="card card-pad"><h2>${esc(x.name)}</h2><div class="mt12">${badge(x.state)}</div><p class="note-text mt12">字段映射 ${x.mappings.length} 项 · 配置版本 ${x.version}</p><div class="mt16 flex wrap">${act('配置映射','connection',x.id,'sm')}${act('本地报文校验','mapping-trial',x.id,'sm')}</div></div>`).join('')}</div><div class="card mt20"><div class="card-head"><h2>同步任务记录</h2><span class="subtle">保留每次失败及后续处理结果</span></div>${table(['时间','任务类型','状态','尝试次数','原因','操作'],t.items.map(x=>[ts(x.created_at),esc(x.payload.data_type),badge(x.state),x.attempts,esc(x.error),link('详情','task',x.id)]))}</div>`},
 async operations(){const d=await api('/operations');view=d;return pageHead('真实运行信息与现场验收门槛；未检测的项目不显示通过。')+`<div class="system-health"><div class="card card-pad"><h2>数据库</h2><p class="inline-metric mt16">${esc(d.database_engine)}</p><p class="note-text">${d.database_reachable?'连接正常':'连接异常'} · ${esc(d.environment)}</p></div><div class="card card-pad"><h2>后台任务进程</h2><div class="mt16">${badge(d.worker.healthy?'运行正常':'尚无有效心跳')}</div><p class="note-text mt12">最后心跳 ${ts(d.worker.last_heartbeat)}</p></div><div class="card card-pad"><h2>存储剩余空间</h2><p class="inline-metric mt16">${d.free_gib} GiB</p><p class="note-text">文件、导出与日志需定期核查空间</p></div></div><div class="equal2 mt20"><div class="card card-pad"><h2>最近备份记录</h2>${json(d.backup)}<p class="note-text mt12">有备份文件不代表能够恢复。按交付运维手册在独立空库执行恢复演练。</p></div><div class="card card-pad"><h2>PDF 现场验收条件</h2>${table(['项目','指标'],[['普通业务页面','原则上 ≤ 3 秒'],['复杂统计分析','原则上 ≤ 5 秒'],['同时在线','3000 人'],['并发访问','不少于 100 用户'],['真实业务双轨比对','积分 / 考核样本 100% 一致']])}<p class="note-text mt12">上述为采购要求，不是本环境已经测得的结果。</p></div></div><div class="mt20">${note(d.notes,true)}</div>`},
 async notices(){const d=await api('/notices?'+listQuery());view=d;return pageHead('学校政策、业务通知与操作指引。',can('notice.manage')?act('发布通知','notice-form','','primary','plus'):'')+`<div class="card">${filtersBar()}${table(['通知标题','分类','发布范围','发布时间','操作'],d.items.map(x=>[esc(x.title),esc(x.category),esc(orgName(x.org_id)),ts(x.created_at),link('阅读','notice',x.id)+(can('notice.manage')?link('编辑 / 撤回','notice-form',x.id):'')]))}${pager(d)}</div>`},
 async help(){return pageHead('按角色办理，一次把关键事项办清楚。')+`<div class="equal2">${[['普通教师','先核对培训台账，再上传资质与佐证；资质提交后等待审核。查看积分和考核计算依据，有问题从明细提交核对申请，处理后本人确认。'],['教研室 / 二级学院','从统一待办进入本组织业务，核验材料和计算依据。考核仅在本层级步骤可确认，发现问题说明原因退回，不能跳过教师确认。'],['学校管理部门','先初始化组织、账号、字典和周期；维护积分 / 考核规则并试算。以 Excel 导入或人工录入形成可追溯台账，计算后组织四级确认，最后归档。'],['管理员运维','教师批量导入后账号默认停用，先配置并启用。每日核查任务进程、磁盘和备份，定期独立恢复演练。机房上线前须完成真实 MySQL、100 并发、3000 在线与脱敏真实案例比对。']].map(([t,b])=>`<section class="card card-pad"><h2>${t}</h2><p class="policy-text mt16">${b}</p></section>`).join('')}</div><div class="card card-pad mt20"><h2>常见问题</h2><div class="policy"><h3>为什么不能改已确认或归档的数据？</h3><p>积分通过追加差额纠错；已确认的积分需授权留痕解锁。考核须按流程退回后重算，已归档不可覆盖，应新建更正周期，原周期继续保留。</p><h3>导出没有立即下载怎么办？</h3><p>进入“导出与任务中心”查看后台任务。长时间排队时由管理员检查 worker 进程；权限变化后应重新导出，不能继续下载旧范围文件。</p><h3>Excel 为什么要再次点击确认？</h3><p>上传后只生成预览与错误行，不写业务表。确认时再次校验当前权限和数据重复情况，全批次在同一事务中入库。</p><h3>没有接学校接口能用吗？</h3><p>本地账号、手工台账和 Excel 可独立运行。统一认证、学校数据中台、湘培直通车尚未接通，不能把本地校验结果当成外部同步成功。</p></div></div>`}
};
async function download(path,filename){const r=await api(path,{raw:true});const disp=r.headers.get('Content-Disposition')||'';if(!filename){const utf=disp.match(/filename\*=UTF-8''([^;]+)/i),plain=disp.match(/filename="?([^";]+)/i);filename=utf?decodeURIComponent(utf[1]):plain?.[1]}const blob=await r.blob();const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=filename||'下载文件';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function saved(message='已保存到学校业务库'){closeModal();toast(message);await render()}
function actionForm(title,url,obj,action,{basis=false,after}={}){formModal(title,reasonFields(),async v=>{await api(url,{method:'POST',body:{...v,expected_version:obj.version,action}});if(after){closeModal();await after()}else await saved()},{submit:title,hint:basis?'请核对影响范围后填写原因和依据。':'此操作由当前登录账号办理，服务端将再次校验权限、版本与业务状态。'})}
function changePassword(forced=false){formModal(forced?'首次登录修改临时密码':'修改登录密码',field('old_password','当前密码','password')+field('new_password','新密码（至少 12 位）','password')+field('repeat','再次输入新密码','password'),async v=>{if(v.new_password!==v.repeat)throw Error('两次新密码不一致');delete v.repeat;await api('/auth/password',{method:'POST',body:v});closeModal();me=null;loginView('密码已修改，请使用新密码登录。')},{submit:'修改并重新登录',hint:'密码不能只有数字或只有字母。修改后所有旧登录会话失效。'})}
async function recordForm(id){let x=id?(await api('/records/'+id)).record:{};
 formModal(id?'更正培训业务记录':'新增培训业务记录',teacherField(x.teacher_id||'')+field('external_key','来源唯一编号','text',x.external_key||'',{readonly:!!id})+field('event_date','业务日期','date',x.event_date||new Date().toISOString().slice(0,10))+field('source','数据来源','text',x.source||'经核对人工录入')+field('project_code','项目编码','text',x.project_code||'')+field('project','项目名称','text',x.project||'')+field('course_code','课程编码','text',x.course_code||'')+field('course','课程名称','text',x.course||'')+field('class_code','班级编码','text',x.class_code||'')+field('class_name','班级名称','text',x.class_name||'')+field('hours','授课学时','number',x.hours||0,{min:0,step:0.01})+field('participants','课程人次','number',x.participants||0,{min:0,step:1})+field('income','归属培训收入（元）','number',x.income||0,{step:0.01})+reasonFields(),async v=>{delete v.teacher_id_search;if(id)v.expected_version=x.version;await api('/records'+(id?'/'+id:''),{method:id?'PUT':'POST',body:v});await saved()},{wide:true,submit:'保存业务数据',hint:'同一来源唯一编号不能重复入账。退款或收入更正可填负数，不改变原有考核归档快照。'})
}
async function showRecord(id){const d=await api('/records/'+id),x=d.record;modalContext=x;
 modal('培训数据明细',`<dl class="kv"><dt>所属教师</dt><dd>${esc(teacherName(x.teacher_id))}</dd><dt>项目 / 课程</dt><dd>${esc(x.project)} / ${esc(x.course)}</dd><dt>日期 / 班级</dt><dd>${x.event_date} / ${esc(x.class_name)}</dd><dt>学时 / 人次</dt><dd>${number(x.hours,2)} 学时 / ${x.participants} 人次</dd><dt>归属培训收入</dt><dd>${number(x.income,2)} 元</dd><dt>数据来源</dt><dd>${esc(x.source)}</dd><dt>来源唯一编号</dt><dd class="mono">${esc(x.external_key)}</dd></dl><h3 class="mt20">版本与调整依据</h3>${d.history.map(r=>`<details class="mt12"><summary>v${r.version} · ${esc(r.reason)}</summary>${json(r.data)}</details>`).join('')}`,act('关闭','close')+(x.teacher_id===me.user.id?act('对该记录提出核对','new-dispute','record|'+id,'primary','help'):''));
}
async function qualificationForm(id){const cats=await api('/qualification-categories');let x=id?(await api('/qualifications/'+id)).qualification:{};
 formModal(id?'补充 / 变更我的资质':'新增我的资质',field('category','资质类别','select',x.category||cats.categories[0],{options:cats.categories})+field('name','证书名称','text',x.name||'')+field('certificate_no','证书编号','text',x.certificate_no||'')+field('issuer','发证机构','text',x.issuer||'')+field('obtained','取得日期','date',x.obtained||'')+field('expires','有效期至','date',x.expires||'',{required:false,hint:'长期有效可留空；判定考核资质以周期结束日是否有效为准。'})+reasonFields(),async v=>{v.teacher_id=me.user.id;v.expires=v.expires||null;if(id)v.expected_version=x.version;const r=await api('/qualifications'+(id?'/'+id:''),{method:id?'PUT':'POST',body:v});closeModal();await render();await showQualification(r.id)},{wide:true,submit:'保存并补充附件',hint:'保存后仍是草稿。请上传真实 PDF / PNG / JPG，再提交审核；本页面不会把草稿直接标为审核通过。'})
}
async function showQualification(id){const d=await api('/qualifications/'+id),x=d.qualification;modalContext=x;const own=x.teacher_id===me.user.id;
 let actions=act('关闭','close');if(own&&x.state!=='SUBMITTED')actions+=act('编辑资料','qualification-form',id,'','edit');if(own&&['DRAFT','RETURNED'].includes(x.state))actions+=act('上传佐证','upload','qualification|'+id,'','plus')+act('提交审核','qual-action','submit|'+id,'primary','check');if(own&&x.state==='SUBMITTED')actions+=act('撤回修改','qual-action','withdraw|'+id);
 if(!own&&can('qualification.review')&&x.state==='SUBMITTED')actions+=act('退回补充','qual-action','return|'+id,'danger')+act('审核通过','qual-action','approve|'+id,'primary','check');
 modal('教师资质 · '+x.name,`<div class="between"><div><h2>${esc(x.name)}</h2><p class="muted small mt8">${esc(teacherName(x.teacher_id))} · ${esc(x.category)} · v${x.version}</p></div>${badge(x.state)}</div><dl class="kv mt20"><dt>证书编号</dt><dd>${esc(x.certificate_no)}</dd><dt>发证机构</dt><dd>${esc(x.issuer)}</dd><dt>取得时间</dt><dd>${x.obtained}</dd><dt>有效期至</dt><dd>${x.expires||'长期有效'}</dd></dl><h3 class="mt20">当前版本材料</h3>${downloads(d.attachments)}${own&&['DRAFT','RETURNED'].includes(x.state)?d.attachments.map(a=>`<div class="mt8">${link('从当前材料移除：'+a.name,'detach',a.id)}</div>`).join(''):''}<div class="equal2 mt20"><div><h3>审核流转</h3>${eventsHtml(d.events)}</div><div><h3>历史版本（不可覆盖）</h3>${d.revisions.map(r=>`<details class="mt12"><summary>v${r.version} · ${esc(r.reason)}</summary>${json(r.data)}${r.attachment_ids.map(a=>`<div class="mt8">${act('下载历史佐证','attachment-download',a,'sm')}</div>`).join('')}</details>`).join('')}</div></div>`,actions,true);
}
async function upload(kind,id){const d=await api('/'+(kind==='qualification'?'qualifications':'disputes')+'/'+id),x=d[kind];formModal('上传业务佐证',field('file','选择附件','file','',{accept:'.pdf,.png,.jpg,.jpeg',full:true})+field('reason','上传依据','textarea','',{full:true}),async(v,f)=>{const fd=new FormData(f);fd.set('expected_version',String(x.version));await api(`/attachments/${kind}/${id}`,{method:'POST',body:fd});closeModal();await render();await(kind==='qualification'?showQualification(id):showDispute(id))},{submit:'上传并绑定业务',hint:'单文件最大 10 MiB。文件由服务端校验，绑定业务和权限，不提供公开下载地址。'})}
async function showPoint(id){const x=await api('/points/'+id);modalContext=x;modal('积分计算依据',`<div class="between"><div><h2>${esc(teacherName(x.teacher_id))} · ${esc(x.item_key)}</h2><p class="small muted mt8">${esc(periodName(x.period_id))}</p></div><strong class="assessment-total">${Number(x.amount)>0?'+':''}${number(x.amount,2)}</strong></div><div class="formula mt20">${esc(x.formula)}</div><dl class="kv mt20"><dt>类型</dt><dd>${badge(x.kind)}</dd><dt>规则 / 批次</dt><dd class="mono">${esc(x.rule_id||'人工复核')}<br>${esc(x.batch_id||'独立调整项')}</dd><dt>调整原因</dt><dd>${esc(x.reason)}</dd><dt>依据</dt><dd>${esc(x.basis)}</dd><dt>计算时间</dt><dd>${ts(x.created_at)}</dd></dl>${detailSections(x.source_snapshot)}`,act('关闭','close')+(x.teacher_id===me.user.id?act('提出核对申请','new-dispute','points|'+id,'primary','help'):''),true)}
async function calculate(kind){if(!periods.some(p=>p.state==='OPEN'))throw Error('请先新建开放的考核周期。');const options=periods.filter(p=>p.state==='OPEN').map(p=>[p.id,p.name]);
 formModal(kind==='points'?'计算 / 重算教师积分':'生成 / 重算三级考核',field('period_id','适用周期','select',periodId||options[0]?.[0],{options,full:true})+`<div class="form-field full"><label>选择教师（每批最多 200 人） <b>*</b></label><div class="flex"><input id="calc-search" placeholder="输入姓名或工号检索"><button type="button" class="btn" data-action="calc-search">检索</button><button type="button" class="btn" data-action="calc-all">选择当前列表</button></div><div id="calc-people" class="checkbox-list mt12">${teachers.filter(t=>t.active).map(t=>`<label><input type="checkbox" name="person" value="${t.id}">${esc(t.name)} · ${esc(t.staff_no)}</label>`).join('')}</div><p class="hint">通过检索选择教师；已归档或未经退回的考核不会被重算覆盖。</p></div>`+(kind==='points'?field('item_keys','仅重算指定积分项编码','text','',{required:false,full:true,hint:'多个编码用英文逗号分隔；留空计算全部规则项。'}):'')+reasonFields(),async(v,f)=>{const ids=$$('input[name=person]:checked',f).map(i=>i.value);if(!ids.length)throw Error('至少选择一名教师');const body={period_id:v.period_id,teacher_ids:ids,reason:v.reason,basis:v.basis};if(kind==='points'&&v.item_keys)body.item_keys=v.item_keys.split(',').map(x=>x.trim()).filter(Boolean);const d=await api('/'+(kind==='points'?'points':'assessments')+'/calculate',{method:'POST',body});periodId=v.period_id;closeModal();await render();modal('计算批次已完成',note('结果已真实写入业务表；计算成功不等于学校已确认考核结果。')+json({batch_id:d.batch_id,teachers:d.items?.length,summary:d.summary}),act('返回台账','close'));},{wide:true,submit:'确认计算入库'})}
async function pointAdjust(){const open=periods.filter(p=>p.state==='OPEN');formModal('追加积分调整项',teacherField('')+field('period_id','考核周期','select',periodId||open[0]?.id,{options:open.map(p=>[p.id,p.name])})+field('item_key','调整项编码','text','manual_review')+field('amount','调整分值（负数为冲销）','number',0,{step:0.01})+reasonFields(),async v=>{delete v.teacher_id_search;if(!v.basis||v.basis.length<2)throw Error('人工调整必须填写依据');await api('/points/adjust',{method:'POST',body:v});await saved('已追加调整流水，原始明细没有被改写')},{wide:true,submit:'追加调整项'})}
async function showAssessment(id){const d=await api('/assessments/'+id),x=d.assessment;modalContext=x;const match={TEACHER:'teacher',DEPARTMENT:'dept',COLLEGE:'college',SCHOOL:'school',READY:'school'}[x.state]===me.role.kind;
 let actions=act('关闭','close');if(can('export'))actions+=act('打印结果','print',id,'','print');if(x.teacher_id===me.user.id&&x.state!=='ARCHIVED')actions+=act('提出核对','new-dispute','assessment|'+id);
 if(match){if(me.role.kind!=='teacher')actions+=act('退回教师核对','assess-action','return|'+id,'danger');actions+=act(x.state==='READY'?'归档结果':me.role.kind==='teacher'?'本人确认':'确认并提交下一级','assess-action',(x.state==='READY'?'archive':'confirm')+'|'+id,'primary','check')}
 if(x.state==='TEACHER'&&can('assessment.calculate'))actions+=act('留痕更正分值','score-adjust',id);
 const stages=['TEACHER','DEPARTMENT','COLLEGE','SCHOOL','READY','ARCHIVED'];
 modal('考核详情 · '+teacherName(x.teacher_id),`<div class="between"><div><h2>${esc(periodName(x.period_id))}</h2><p class="muted small mt8">${esc(d.rule.name)} · 规则版本 ${d.rule.version_no}</p></div><div><strong class="assessment-total">${number(x.score,2)}</strong><span class="muted"> 分</span></div></div><div class="flow-strip mt20">${stages.map((s,i)=>`<div class="flow-step ${s===x.state?'active':i<stages.indexOf(x.state)?'done':''}"><i>${i+1}</i>${labels[s]}</div>`).join('')}</div>${table(['指标','原始值','计算公式','分值'],x.detail.map(t=>[esc(t.label),esc(t.raw),`<span class="small">${esc(t.formula)}</span>`,number(t.score,2)]))}${x.state==='ARCHIVED'?`<div class="state-lock mt16">${icon('lock')}已归档 · 规则、业务数据与材料快照已冻结</div><p class="mono mt8">SHA256 ${esc(x.archive_sha256)}</p>`:''}<h3 class="mt20">办理轨迹</h3>${eventsHtml(d.events)}${detailSections(x.state==='ARCHIVED'?x.archive:x.source_snapshot)}`,actions,true);
}
async function scoreAdjust(id){const x=(await api('/assessments/'+id)).assessment;formModal('追加考核复核更正项',field('delta','调整分值（可为负数）','number',0,{min:-100,max:100,step:0.01,full:true})+reasonFields(),async v=>{if(!v.basis||v.basis.length<2)throw Error('请填写更正依据');await api('/assessments/'+id+'/adjust',{method:'POST',body:{...v,expected_version:x.version}});closeModal();await render();await showAssessment(id)},{submit:'保存更正项',hint:'更正只在教师确认环节允许。保留原始评分项，新增调整项及依据，不改写已归档结果。'})}
async function printAssessment(id){const d=await api('/assessments/'+id+'/print'),x=d.assessment;$('.print-sheet')?.remove();const el=document.createElement('section');el.className='print-sheet';el.innerHTML=`<h1>非学历教育考核结果</h1><p>学校：${esc(me.school_name)}　教师：${esc(d.teacher.name)}　工号：${esc(d.teacher.staff_no)}</p><p>周期：${esc(d.period.name)}　状态：${esc(labels[x.state])}　总分：${number(x.score,2)}</p><table><thead><tr><th>指标</th><th>原始值</th><th>计算过程</th><th>分值</th></tr></thead><tbody>${x.detail.map(i=>`<tr><td>${esc(i.label)}</td><td>${esc(i.raw)}</td><td>${esc(i.formula)}</td><td>${number(i.score,2)}</td></tr>`).join('')}</tbody></table><p>归档校验：${esc(x.archive_sha256||'尚未归档，本打印件不替代最终确认结果')}</p><small>业务编号 ${esc(x.id)}　打印人 ${esc(me.user.name)}　时间 ${new Date().toLocaleString('zh-CN')}</small>`;document.body.append(el);document.body.classList.add('print-mode');window.print();document.body.classList.remove('print-mode')}
async function newDispute(code){const[k,id]=code.split('|');formModal('提交本人数据核对申请',reasonFields(),async v=>{const d=await api('/disputes',{method:'POST',body:{...v,object_type:k,object_id:id}});closeModal();await nav('disputes');await showDispute(d.id)},{submit:'提交核对申请',hint:'请描述有异议的基础数据或计算依据。未解决的申请会阻止相关考核确认。'})}
async function showDispute(id){const d=await api('/disputes/'+id),x=d.dispute;modalContext=x;let actions=act('关闭','close');if(x.state==='OPEN'){actions+=act('补充佐证','upload','dispute|'+id);if(can('dispute.resolve')&&x.teacher_id!==me.user.id)actions+=act('完成复核','resolve',id,'primary','check')}
 modal('数据核对申请',`<dl class="kv"><dt>教师</dt><dd>${esc(teacherName(x.teacher_id))}</dd><dt>状态</dt><dd>${badge(x.state)}</dd><dt>核对原因</dt><dd>${esc(x.reason)}</dd><dt>目标业务</dt><dd>${act('查看原业务','todo',`${x.object_type}|${x.object_id}`,'text')}</dd><dt>复核结果</dt><dd>${esc(x.resolution||'等待授权人员核对')}</dd></dl><h3 class="mt20">佐证材料</h3>${downloads(d.attachments)}<h3 class="mt20">办理轨迹</h3>${eventsHtml(d.events)}`,actions,true)}
