async function showImport(id,rowPage=1){const d=await api('/imports/'+id+'?'+query({page:rowPage,size:30})),x=d.job;modalContext={...x,rowPage};modal('Excel 导入预览',`<div class="between"><div><h2>${esc(x.filename)}</h2><p class="small muted mt8">数据 ${x.total} 行 · 错误 ${x.errors} 行 · SHA256 ${x.sha256.slice(0,16)}…</p></div>${badge(x.state)}</div>${x.errors?note('存在错误行，整批禁止确认。请下载错误行，修正原 Excel 后重新上传。',true):note(x.state==='COMMITTED'?'已经真实入库，回执记录每一行生成的业务编号。':'校验通过，但尚未入库。点击“确认入库”后服务端再次校验并提交事务。')}<div class="mt16">${table(['Excel 行号','原始字段','校验结果'],d.rows.items.map(r=>[r.row_no,`<div class="small" style="max-width:680px;white-space:normal">${esc(Object.values(r.payload.raw).join(' / '))}</div>`,r.errors.length?`<span class="red small">${esc(r.errors.join('；'))}</span>`:badge('校验通过')]))}</div><div class="flex mt12"><span class="muted small">第 ${d.rows.page} 页 / 共 ${d.rows.total} 行</span>${d.rows.page>1?act('上一页','import-page',id+'|'+(d.rows.page-1),'sm'):''}${d.rows.page*d.rows.size<d.rows.total?act('下一页','import-page',id+'|'+(d.rows.page+1),'sm'):''}</div>${x.receipt?.written?detailSections(x.receipt):''}`,act('关闭','close')+(x.errors?act('下载错误行 Excel','import-errors',id,'','download'):'')+(x.state==='PREVIEW'&&!x.errors?act('确认入库','import-confirm',id,'primary','check'):''),true)}
